// The same user text, four output contexts, four correct encodings.
const userText = '<img src=x onerror=alert(1)>' // harmless probe string

// Context 1: HTML body -> escape markup characters
function escapeHtml(s) {
  const map = { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }
  return s.split("").map((ch) => map[ch] || ch).join("")
}
document.getElementById("bio").textContent = userText // DOM does the work

// Context 2: HTML attribute -> escape + always quote the attribute
el.setAttribute("title", escapeHtml(userText))

// Context 3: URL parameter -> percent-encoding
const url = "https://example.com/search?q=" + encodeURIComponent(userText)

// Context 4: data attribute consumed by JS -> pass JSON, not markup
el.dataset.payload = JSON.stringify({ note: userText })

